<?php declare(strict_types=1); $adminDashboard = $adminDashboard ?? []; ?>
<section class="view hidden" id="view-admin-dashboard" data-title="Admin overview" data-section="Administration">
  <div class="page-heading"><div><span class="eyebrow gold-eyebrow">ADMINISTRATION</span><h1>Community overview</h1><p class="muted">Live statistics from the ClubConnect database.</p></div><button class="button button-dark" data-view="admin-events">Review events</button></div>
  <div class="metric-grid admin-metrics"><article class="metric-card"><span class="metric-icon blue">♙</span><div><strong><?= e($adminDashboard['students'] ?? 0) ?></strong><span>Students</span></div></article><article class="metric-card"><span class="metric-icon purple">♧</span><div><strong><?= e($adminDashboard['clubs'] ?? 0) ?></strong><span>Clubs</span></div></article><article class="metric-card"><span class="metric-icon orange">◫</span><div><strong><?= e($adminDashboard['events'] ?? 0) ?></strong><span>Events</span></div></article><article class="metric-card"><span class="metric-icon green">♢</span><div><strong><?= e($adminDashboard['memberships'] ?? 0) ?></strong><span>Memberships</span></div></article><article class="metric-card"><span class="metric-icon blue">✓</span><div><strong><?= e($adminDashboard['registrations'] ?? 0) ?></strong><span>Registrations</span></div></article></div>
  <div class="dashboard-grid"><article class="panel"><div class="panel-heading"><div><h2>Recent registrations</h2><p class="muted">Latest student activity.</p></div><button class="text-button" data-view="admin-registrations">View all →</button></div><?php if (($adminDashboard['recent_registrations'] ?? []) === []): ?><div class="empty-state"><p class="muted">No registration activity yet.</p></div><?php else: ?><div class="activity-list"><?php foreach ($adminDashboard['recent_registrations'] as $registration): ?><a class="activity-row" data-view="event-details" data-route="true" href="index.php?view=event-details&amp;id=<?= (int) $registration['event_id'] ?>"><span class="avatar blue">◫</span><div><strong><?= e($registration['user_name']) ?> <?= e($registration['status'] === 'cancelled' ? 'cancelled a registration' : 'registered') ?></strong><span><?= e($registration['title']) ?></span></div><small><?= e(date('j M Y', strtotime((string) $registration['registered_at']))) ?></small></a><?php endforeach; ?></div><?php endif; ?></article><article class="panel"><div class="panel-heading"><div><h2>Upcoming events</h2><p class="muted">Next events in the campus calendar.</p></div><button class="text-button" data-view="admin-events">View all →</button></div><?php if (($adminDashboard['upcoming_events'] ?? []) === []): ?><div class="empty-state"><p class="muted">No upcoming events.</p></div><?php else: ?><div class="event-list"><?php foreach ($adminDashboard['upcoming_events'] as $event): ?><a class="event-row" data-view="event-details" data-route="true" href="index.php?view=event-details&amp;id=<?= (int) $event['event_id'] ?>"><span class="date-tile"><strong><?= e(date('d', strtotime((string) $event['event_date']))) ?></strong><span><?= e(strtoupper(date('M', strtotime((string) $event['event_date'])))) ?></span></span><span class="event-info"><strong><?= e($event['title']) ?></strong><span><?= e($event['club_name']) ?> · <?= e($event['venue']) ?></span></span></a><?php endforeach; ?></div><?php endif; ?></article></div>
  <article class="panel"><div class="panel-heading"><div><h2>Recent club activity</h2><p class="muted">Latest memberships.</p></div><button class="text-button" data-view="admin-clubs">View clubs →</button></div><?php if (($adminDashboard['club_activity'] ?? []) === []): ?><div class="empty-state"><p class="muted">No club membership activity yet.</p></div><?php else: ?><div class="activity-list"><?php foreach ($adminDashboard['club_activity'] as $activity): ?><a class="activity-row" data-view="admin-clubs"><span class="avatar coral">♧</span><div><strong><?= e($activity['user_name']) ?> joined <?= e($activity['club_name']) ?></strong><span>Club membership</span></div><small><?= e(date('j M Y', strtotime((string) $activity['joined_at']))) ?></small></a><?php endforeach; ?></div><?php endif; ?></article>
</section>
